@startuml

class Department {
  + name : string
}

class ResearchGroup {
  + name : string
}

class Researcher {
  + name : string
}

class Project {
  + name : string
}

class WorkPackage {
  + name : string
}

class Assignment {
  + startDate : date
  + endDate : date
}

Department "1" -- "*" ResearchGroup : has
ResearchGroup "1" -- "1..*" Researcher : belongs to
Project "1" *-- "1..*" WorkPackage : decomposed into
ResearchGroup "1" -- "1" WorkPackage : leads
Researcher "1" -- "*" Assignment : performs
WorkPackage "1" -- "*" Assignment : involves

@enduml

